{
  "translations": {
    "L0001": "Quand la pluie a cessé, on s’est revus sous le pont.",
    "L0002": "Aujourd’hui, je compte rentrer en solitaire.",
    "L0003": "Il a dit tout bas : « C’est bon. »",
    "L0004": "Je ne sais si ces mots sont pardon ou résignation.",
    "L0005": "Demain encore, je traverserai peut-être le même pont.",
    "L0006": "Il n’est resté que ces deux caractères : « 東京 »."
  },
  "sourceNotes": []
}
